(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0030.js"] = [{"id":"glyph-seal-916c","script":"seal","character":"酬","reading":"chóu","description":"chóu：(1)劝酒～酢。\n(2)用财物报答～劳。～谢。～金。报～。\n(3)交际往来应（yìng）～。～对。～和（hè）（用诗词应答）。～唱（用诗词互相赠答）。\n(4)实现愿望壮志未～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酬"},{"id":"glyph-seal-9171","script":"seal","character":"酱","reading":"jiàng","description":"用麦、面、豆等发酵制成的调味品\n将鱼、肉、蔬、果捣烂制成的糊状食品\n用酱或酱油腌制\n⒈豆、麦等经过发酵制成的调味品甜～。辣椒～。豆瓣～。\n⒉用酱腌制或加有酱的食品～肉。～黄瓜。杂～面。\n⒊像酱样子的糊状食品肉～。虾～。蕃茄～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酱"},{"id":"glyph-seal-9177","script":"seal","character":"酷","reading":"kù","description":"kù：(1)残忍、暴虐到极点～刑。～吏。残～。严～。冷～。～滥。～虐。\n(2)极，甚，程度深～暑。～热。～寒。～爱。～似。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酷"},{"id":"glyph-seal-9178","script":"seal","character":"酸","reading":"suān","description":"suān：(1)像醋的气味或味道～菜。～溜溜。～梅。～甜。～奶。～枣。\n(2)化学上称能在水溶液中产生氢离子的化合物，分无机酸”、有机酸”两大类盐～。碳～。硝～。硫～。～碱度。\n(3)讥讽人的迂腐穷～‘～。\n(4)悲痛，伤心～楚。辛～（亦作酸辛”）。～苦。～怆。～怀。\n(5)因疲劳或疾病引起的微痛而无力的感觉～痛。腰～腿疼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酸"},{"id":"glyph-seal-9179","script":"seal","character":"酹","reading":"lèi","description":"lèi：把酒洒在地上表示祭奠或起誓一樽还～江月”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酹"},{"id":"glyph-seal-917f","script":"seal","character":"酿","reading":"niàng","description":"酝酿,逐渐形成\n⒈利用发酵作用制造，一般指造酒～造。～酒。\n⒉酒佳～。\n⒊逐渐形成～成。\n⒋蜜蜂制蜜～蜜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-酿"},{"id":"glyph-seal-9185","script":"seal","character":"醅","reading":"pēi","description":"pēi：没滤过的酒盘飧市远无兼味，樽酒家贫只旧～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醅"},{"id":"glyph-seal-9187","script":"seal","character":"醇","reading":"chún","description":"chún：(1)酒味厚～酒。～醪。\n(2)纯粹～和（性质或味道纯正平和）。～厚（气味、滋味纯正浓厚）。～美。～化。\n(3)同淳”。\n(4)有机化合物的一类乙～。胆固～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醇"},{"id":"glyph-seal-9189","script":"seal","character":"醉","reading":"zuì","description":"zuì：(1)饮酒过量，神志不清～汉。～鬼。～意。～拳（一种拳术，步法上突出东倒西歪的醉态）。～生梦死。～翁之意不在酒。\n(2)沉迷，过分爱好～心。沉～。陶～（很满意地沉浸在某种境界或思想活动中）。\n(3)用酒泡制的～枣。～虾。～蟹。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醉"},{"id":"glyph-seal-918b","script":"seal","character":"醋","reading":"cù","description":"cù：一种调味用的液体，味酸米～。熏～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醋"},{"id":"glyph-seal-918d","script":"seal","character":"醍","reading":"tí；tǐ","description":"tí：〔～醐〕古代指从牛奶中提炼出来的酥油，佛教喻最高的佛法，如～～灌顶”（喻把佛法、智慧、悟性灌输给人，使人彻底醒悟，亦借指听了精辟的言论深受启发教育）。\ntǐ：较清的浅红色酒粢～在堂”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醍"},{"id":"glyph-seal-9190","script":"seal","character":"醐","reading":"hú","description":"hú：〔醍（tí）～〕见醍1”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醐"},{"id":"glyph-seal-9192","script":"seal","character":"醒","reading":"xǐng","description":"xǐng：(1)睡眠状态结束或尚未入睡如梦方～。\n(2)酒醉、麻醉或昏迷后神志恢复正常状态～酒。\n(3)泛指头脑由迷糊而清楚～悟。觉（jué）～。清～。提～。猛～。\n(4)明显、清楚～目。～眼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醒"},{"id":"glyph-seal-91a2","script":"seal","character":"醢","reading":"hǎi","description":"hǎi：(1)用肉、鱼等制成的酱。\n(2)古代的一种酷刑，把人杀死后剁成肉酱。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醢"},{"id":"glyph-seal-91aa","script":"seal","character":"醪","reading":"láo","description":"láo：(1)浊酒。\n(2)醇酒。\n〔～糟儿（zāor）〕江米酒。\n〔～醴〕中药剂型之一，即药酒。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醪"},{"id":"glyph-seal-91ae","script":"seal","character":"醮","reading":"jiào","description":"jiào：(1)古代婚娶时用酒祭神的礼再～（再婚）。\n(2)道士设坛念经做法事打～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醮"},{"id":"glyph-seal-91af","script":"seal","character":"醯","reading":"xī","description":"xī：(1)醋。\n(2)酰的旧称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醯"},{"id":"glyph-seal-91b4","script":"seal","character":"醴","reading":"lǐ","description":"lǐ：(1)甜酒。\n(2)甜美的泉水～泉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醴"},{"id":"glyph-seal-91ba","script":"seal","character":"醺","reading":"xūn","description":"xūn：(1)醉微～。醉～～。\n(2)古同熏”，熏染。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-醺"},{"id":"glyph-seal-91c7","script":"seal","character":"采","reading":"cǎi；cài","description":"cǎi：(1)摘取～撷。～花。～摘。～制。\n(2)选取，搜集，开发，利用～访（搜集寻访）。～纳（接受意见）。～集。～伐。～购。～掘。～写。\n(3)神色，精神神～。精～。\n(4)同彩”。\n(5)古代指官。\n〔～～〕盛多的样子。\ncài：〔～地〕古代卿大夫的封地。亦称采邑”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-采"},{"id":"glyph-seal-91ca","script":"seal","character":"释","reading":"shì","description":"解释\n⒈放，放下，放弃～放。开～。如～重负。手不～卷。\n⒉排解，消除，消溶～难。～疑。冰～。\n⒊说明，解说～义。解～。注～。\n释yì 1.喜悦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-释"},{"id":"glyph-seal-91cc","script":"seal","character":"里","reading":"lǐ","description":"内,中。与外相反\n⒈长度单位1公～为1000米，合二市～，即三百丈。\n⒉〈古〉一种居民组织。五家为邻，五邻为～。今指街坊～弄。邻～。\n⒋衣服里层绿衣黄～。〈引〉里面，内部城市～。手掌～。柜子～。\n⒌物体内层，跟\"表\"、\"面\"相对～层。～面。袜～儿。被盖～子。表～如一。\n⒍一定范围以内山～。那～。哪～？黑夜～。\n①靠左边，靠里的那边。\n②〈方〉内行知识～手。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-里"},{"id":"glyph-seal-91cd","script":"seal","character":"重","reading":"zhòng；chóng","description":"zhòng：分量大；程度深；重要，重视。chóng：重复，重叠，再一次。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-91ce","script":"seal","character":"野","reading":"yě","description":"yě：(1)郊外，村外～外。～景。～游。～趣。～餐。～战。四～。郊～。\n(2)界限，范围分～。视～。\n(3)指不当政的地位，与朝（cháo）”相对朝～。下～。在～。～史。\n(4)不讲情理，没有礼貌～蛮。粗～。\n(5)巨大而非分的欲望～心。\n(6)不受约束心玩儿～了。\n(7)不是人工驯养或栽培的（动物或植物）～生。～兽。～味。～花。～菜。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-野"},{"id":"glyph-seal-91cf","script":"seal","character":"量","reading":"liàng；liáng","description":"liáng：(1)确定、计测东西的多少、长短、高低、深浅、远近等的器具～具。～杯。～筒。～角器。\n(2)用计测器具或其他作为标准的东西确定、计测计～。测～。～度。～体温。\n(3)估计，揣测估～。思～。打～。\n质；\nliàng：(1)古代指斗、升一类测定物体体积的器具度～衡。\n(2)能容纳、禁受的限度酒～。气～。胆～。度～。\n(3)数的多少数～。质～。降雨～。限～供应。\n(4)审度～刑。～才录用。～体裁衣（喻从实际情况出发办事）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-量"},{"id":"glyph-seal-91d1","script":"seal","character":"金","reading":"jīn","description":"jīn：(1)一种化学元素，符号Ａｕ，原子序数79，黄赤色，质软黄～。～子。～笔。\n(2)金一类的，具有光泽、延展性，容易传热和导电的固体的通称（汞除外）。～属。五～（旧指金银铜铁锡）∠～（两种或多种金属混合而成的金属）。～文（铸或刻在商周青铜器上的铭文，旧称钟鼎文”）。\n(3)钱现～。基～。挥～如土。\n(4)指兵器或金属制的乐器～革（兵器甲铠的总称，引申指战争）。～声（ａ．钲声；ｂ．钟声）。～鼓（锣鼓）。\n(5)中国古代乐器八音之一。\n(6)喻尊贵、贵重、难得、持久、坚固、有光泽等～兰（友情深）。～刚（梵语意译，喻牢固、锐利、能摧毁一切）。～瓯（ａ．盛酒器；ｂ．喻疆土完整）。～城汤池。\n(7)一些动、植物因颜色似金而得名～鱼。～乌（太阳）。～龟。～丝猴。\n(8)中国朝代名～代。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-金"},{"id":"glyph-seal-91dc","script":"seal","character":"釜","reading":"fǔ","description":"fǔ：(1)古代的一种锅～底抽薪。破～沉舟。\n(2)中国春秋战国时量器名，亦是容量单位，标准不一。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-釜"},{"id":"glyph-seal-9274","script":"seal","character":"鉴","reading":"jiàn","description":"中国古代用青铜制成的镜子\n⒈〈古〉用来盛水或冰的大盆。\n⒉照影水清可～。\n⒊镜子以铜为～，可以正衣冠。〈引〉可以引为儆戒或教训的事引为～戒。殷～不远。\n⒋观察，审察，区别～赏。～定优劣。～别真假。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鉴"},{"id":"glyph-seal-92ae","script":"seal","character":"銮","reading":"luán","description":"古代皇帝车的仪铃,安装在轭首或车衡上方。上部一般为扁圆形的铃,铃内有弹丸,铃上有辐射状的镂孔。下部为长方形的座;座的两面常有钉孔。西周时开始流行\n皇帝的车驾,因用作帝王的代称","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-銮"},{"id":"glyph-seal-92c8","script":"seal","character":"鋈","reading":"wù","description":"wù：(1)白色金属。\n(2)镀。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鋈"},{"id":"glyph-seal-933e","script":"seal","character":"錾","reading":"zàn","description":"小凿,雕凿金石的工具\n雕,刻\n磨刀出锋\n錾刀\n錾子\n⒈雕凿金石的小凿子钢～子。\n⒉在金石上雕刻～字画。～花纹。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-錾"},{"id":"glyph-seal-936a","script":"seal","character":"鍪","reading":"móu","description":"móu：古代的一种锅。\n〔兜～〕古代打仗时戴的盔。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-鍪"},{"id":"glyph-seal-9488","script":"seal","character":"针","reading":"zhēn","description":"缝缀衣物的用具。也叫引线”\n⒈缝、补衣物时引线用的一种细长的工具缝～。穿～引线。\n⒉形状像针的东西松～。大头～。金～菜。钟表上的时～、分～、秒～。\n⒊用于医疗的有关针的器具、药品等～头。银～。扎～。打～。防疫～。～剂。～灸疗法。～刺麻醉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-针"},{"id":"glyph-seal-9489","script":"seal","character":"钉","reading":"dìng","description":"钉子\n通常是圆锥形,有尖头或尖顶的木料、金属或其他材料做的钉状物\n紧跟不放,监视\n催促;监督;紧迫\n用钉\n①竹、木、金属等制成的细棍形物件。一端有扁平的头，另一端尖锐，主要起固定或连接作用，也可以用来悬挂物品。\n②紧跟着不放松～住对方。\n③督促；催问经常～着点。\n④同'盯'。又见dìng。\n【钉螺】软体动物。螺壳厚，高10毫米左右，螺层7个左右，雌雄异体。生活在杂草丛生的河湖、沟渠、池塘。水陆两栖。是日本血吸虫的中间宿主。\n【钉梢】暗中紧跟在别人身后以监视别人的行动。又作盯梢。\n【钉是钉， 铆是铆】见【丁是丁，卯是卯】。\n①把钉子捶入～皮鞋。\n②用针线缝住～衣扣。又见dīng。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钉"},{"id":"glyph-seal-948a","script":"seal","character":"钊","reading":"zhāo","description":"用勇气、精神或希望鼓舞\n钊zhāo勉励。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钊"},{"id":"glyph-seal-948e","script":"seal","character":"钎","reading":"qiān","description":"钎子\n钎焊","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钎"},{"id":"glyph-seal-948f","script":"seal","character":"钏","reading":"chuàn","description":"臂镯的古称。俗称镯,镯子。用珠子或玉石等穿起来做成的镯子\n钏子\n钏 chuàn镯子金～、玉～。\n钏chuàn用珠子或玉石等穿制成的镯子玉～。金～子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钏"},{"id":"glyph-seal-9493","script":"seal","character":"钓","reading":"diào","description":"引申为诱取\n①将饵挂在钓钩上放入水中诱捕鱼虾等～鱼。\n③钓鱼钩垂～。\n【钓鱼岛】中国台湾省的附属岛屿。在台湾岛东北约180公里处，面积约5平方公里。自古以来是中国的领土。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钓"},{"id":"glyph-seal-9497","script":"seal","character":"钗","reading":"chāi","description":"借指妇女","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钗"},{"id":"glyph-seal-949d","script":"seal","character":"钝","reading":"dùn","description":"呆;笨拙\n①不锋利；不锐利刀～了。\n②笨拙；不灵活迟～。\n【钝角】大于直角小于平角的角。若a为钝角，则90°","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钝"},{"id":"glyph-seal-949e","script":"seal","character":"钞","reading":"chāo","description":"掠取;抢掠◇作抄”\n誊写。也作抄”\n纸币名。现在称纸币为钞票,简称钞\n泛指钱\n⒈纸币～票。现～。\n⒉通\"抄\"。誊写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钞"},{"id":"glyph-seal-949f","script":"seal","character":"钟","reading":"zhōng","description":"钟磬置水中。\n独以此钟名。\n如钟鼓不绝。\n⒈一种金属制的响器，中空，悬挂在架上，用槌敲击发声撞～。打～。警～。\n⒉计时器闹～。电～。石英～。\n⒊时间，小时五分～。八点～。\n⒋杯子，〈古〉一种盛酒器聚酒千～。\n⒌专注，特别～情。～爱。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钟"},{"id":"glyph-seal-94a4","script":"seal","character":"钤","reading":"qián","description":"官印\n通权”。权谋,谋略\n盖章,盖印\n钤记\n⒉盖印章～印。～章。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钤"},{"id":"glyph-seal-94a6","script":"seal","character":"钦","reading":"qīn","description":"旧时对帝王的决定、命令或其所做的事冠以钦”字,以示崇高与尊敬\n敬佩\n⒈恭敬，敬重～爱。～佩。\n⒉〈古〉有关皇帝的～赐。～命。～差大臣。\n钦qìn 1.用手按。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钦"},{"id":"glyph-seal-94a7","script":"seal","character":"钧","reading":"jūn","description":"制陶器所用的转轮\n⒊敬词。对尊长或上级的敬称～座。～鉴。～谕。\n⒋〈古〉通\"均\"。平均。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钧"},{"id":"glyph-seal-94a9","script":"seal","character":"钩","reading":"gōu","description":"形状弯曲,用于探取、悬挂器物的用品。可分为钓钩、挂钩、带钩等\n⒈弯曲的器具，用于悬挂或探取东西等火～儿。钓鱼～。挂衣～子。\n⒉形状像钩的东西～鼻子。蝎子的～儿。\n⒌缝纫编结法之一～边。～花。\n⒍同\"gōu㈠勾\n⒉\"，描绘～图样。\n钩qú 1.见\"钩町\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钩"},{"id":"glyph-seal-94ab","script":"seal","character":"钫","reading":"fāng","description":"古代盛酒浆或粮食的容器,青铜制成,方口大腹\n⒈化学元素之一，具有放射性。符号fr。\n⒉〈古〉一种口方腹大的盛酒壶。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钫"},{"id":"glyph-seal-94ae","script":"seal","character":"钮","reading":"niǔ","description":"器物上面可以提携或系绳带的部分\n交互而成的扣结\n器物上用手操作、转动的部分\n钮niǔ扣合衣物的东西～扣子。塑料～扣。\n钮chǒu 1.刑具。枷锁镣铐之类。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钮"},{"id":"glyph-seal-94af","script":"seal","character":"钯","reading":"bǎ","description":"一种银白色的、有延展性的金属元素，符号pd。银白色，富于延伸性。能大量吸附氢、氧等。可用来提取氢气，还可用于制催化剂。它的合金可用于制电阻线、电器仪表等。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钯"},{"id":"glyph-seal-94b1","script":"seal","character":"钱","reading":"qián","description":"金属货币。特指铜钱\n⒈货币～币。铜～。金～。三块～。\n⒉费用，款项米～。菜～。一笔～。\n⒊财物无～难办。有～有势。\n⒋重量单位十分为一～。十～为一两。\n钱jiǎn 1.古农具名。臿属，似今之铁铲。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钱"},{"id":"glyph-seal-94b2","script":"seal","character":"钲","reading":"zhēng","description":"古代乐器名。形如钤,有柄可执,行军时用\n钟身正面的上部\n⒈〈古〉行军时用的一种铜制打击乐器。\n⒉钲zhèng化学元素\"镄\"的旧称。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钲"},{"id":"glyph-seal-94b3","script":"seal","character":"钳","reading":"qián","description":"古刑具。束颈的铁圈\n夹持东西的用具\n古代刑罚。用铁圈束颈、手、足\n⒈夹东西的工具止血～。老虎～子。\n⒉用工具夹住。〈引〉用强力限制，约束～制。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钳"},{"id":"glyph-seal-94ba","script":"seal","character":"钺","reading":"yuè","description":"星名。钺星,即天","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钺"},{"id":"glyph-seal-94bb","script":"seal","character":"钻","reading":"zuàn","description":"钻研,集中精力学习,推究事理\n⒉细致深入地研究～研。她很有～劲。\n⒊想方设法巴结有权势的人，以谋取私利～营。\n⒈钻子，穿孔打眼的用具电～。手摇～子。\n⒉穿孔，打眼。\n钻qián 1.铁钳之类的刑具。参见\"钻钻\"。 2.同\"钳\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钻"},{"id":"glyph-seal-94bf","script":"seal","character":"钿","reading":"diàn","description":"以金银珠宝介壳镶嵌器物\n衬垫\n钿头\n①用金翠珠宝等制成的花朵形的首饰。\n②把金银贝壳之类镶嵌在器物上。\n⒈〈方〉钱，硬币铜～。银～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-钿"},{"id":"glyph-seal-94c1","script":"seal","character":"铁","reading":"tiě","description":"铁制的器物\n⒈金属元素。符号fe。灰白色，质坚硬，有光泽，富于延伸性，在潮湿空气中易氧化生绣。在工业上用途很大，可以炼钢，制造各种机械、器具等。\n⒉〈喻〉坚固，坚硬、坚强，坚定铜墙～壁。～拳，～人。～姑娘队。\n⒊〈喻〉确定不移～证。～的纪律。\n⒋〈喻〉残暴或精锐～蹄。～骑。\n⒌兵器的代称手无寸～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铁"},{"id":"glyph-seal-94c3","script":"seal","character":"铃","reading":"líng","description":"铃的鸣响或声音,可作为信号\n铃状物\n⒈金属制成的响器，中有小锤，振动发音车～。电～。打～。\n⒉像铃状的东西哑～。棉～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铃"},{"id":"glyph-seal-94c4","script":"seal","character":"铄","reading":"shuò","description":"销毁\n削弱\n秦先得齐宋,则韩氏铄,韩氏铄则楚孤而\n⒈发光的样子闪～。光～如闪电。\n⒉熔化金属～金。销～。\n⒊削弱，毁坏，消灭。\n铄yuè 1.烙;烧灼。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铄"},{"id":"glyph-seal-94c5","script":"seal","character":"铅","reading":"qiān","description":"青金\n古时也指锡类\n一种重而柔软、有延展性、可塑性而没有弹性的二价或四价的金属元素,元素符号pb。原子序数82,刚切割时呈蓝白色,但在潮湿空气中很快失去光泽而变暗灰色,它大多以化合\n状态存在\n⒈金属化学元素。符号pb。银灰色，质软，熔点低。用作制电缆、煤气管、蓄电池等∠金用做铅字、轴承、电线包皮等。\n⒉石墨～笔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铅"},{"id":"glyph-seal-94c9","script":"seal","character":"铉","reading":"xuàn","description":"比喻三公等重臣\n弓弦。通弦”\n琴弦,乐器上发声的线。通弦”\n铉xuàn横贯鼎耳用于扛鼎的器具。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铉"},{"id":"glyph-seal-94ca","script":"seal","character":"铊","reading":"tā","description":"大,主要以化合物的形式应用\n⒈金属化学元素之一。符号tl。灰白色，质软。铊的盐类有毒。铊用于制合金、光电管、温度计、光学玻璃等。\n⒈秤锤。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铊"},{"id":"glyph-seal-94cd","script":"seal","character":"铍","reading":"pí","description":"中医用的长针\n兵器。双刃刀。一说是大矛\n假借为颇”。偏,不平正\n通\"披\"。纷乱。\n铍pí 1.金属元素。符号be。浅灰色，是最轻的金属之一。透x射线的能力最强，可用来制造x射线管。铍铝合金质坚硬而轻，应用于飞机﹑火箭制造业中。铍和青铜的合金弹性\n很强，用来制弹簧。金属铍也用在原子能工业中。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铍"},{"id":"glyph-seal-94ce","script":"seal","character":"铎","reading":"duó","description":"挂在牛马颈下或屋檐下的小铃\n刺;啄\n铎 duó古代宣布政令或战事时用的大铃。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铎"},{"id":"glyph-seal-94d7","script":"seal","character":"铗","reading":"jiá","description":"剑柄\n⒈夹取东西的金属用具火～儿。铁～子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铗"},{"id":"glyph-seal-94d9","script":"seal","character":"铙","reading":"náo","description":"古代打击乐器，形似铃而无舌；也用于“铙钹”，一种金属打击乐器。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-94db","script":"seal","character":"铛","reading":"chēng","description":"锒铛。锁系囚人的铁索\n女子的耳饰\n钟鼓的声音\n温器,似锅,三足\n烙饼或做菜用的平底浅锅\n⒈一种平底浅锅。\n铛dāng 1.见\"锒铛\"。 2.女子的耳饰。 3.象声词。形容撞击金属的声音。\n铛tāng 1.见\"铛?\"。 2.一种小铜鼓。 3.古兵器名。形如半月，有柄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铛"},{"id":"glyph-seal-94dc","script":"seal","character":"铜","reading":"tóng","description":"首衔同凡。\n①金属元素。符号cu。淡紫红色，延展性﹑导电性和导热性都很好。古谓之赤金。铜的合金是电气工业﹑机械工业﹑国防工业等的重要原料。\n③比喻坚强﹑牢固。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铜"},{"id":"glyph-seal-94e0","script":"seal","character":"铠","reading":"kǎi","description":"铠甲\n铠衣","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铠"},{"id":"glyph-seal-94e2","script":"seal","character":"铢","reading":"zhū","description":"现代泰国基本货币单位\n钝,不锋利\n细微\n铢积寸累\n铢两悉称","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铢"},{"id":"glyph-seal-94e3","script":"seal","character":"铣","reading":"xǐ","description":"用一种能旋转的圆形多刃刀具切削金属工件\n铣刀\n铣工\n铣削\n富有光泽的金属\n黄离踵曜,太阳\n⒈金属有光泽。\n⒈使用一种可以旋转的多刃刀切削金属之器件～削。～刀。～床。\n铣xiān 1.铲东西用的一种工具。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铣"},{"id":"glyph-seal-94e4","script":"seal","character":"铤","reading":"dìng","description":"铜铁矿石\n铜铁质的坯料\n熔铸成条块等固定形状的金银,其重数两至数十两不等\n锭子,纺车或纺纱机上绕纱的机件\n快跑的样子\n空;尽\n铤dìng 1.未经加工成器的铜﹑铁。 2.熔铸成条块等固定形状的金属。 3.量词。常用以计块状物。 4.锭子。纺纱机上用来把纤维捻成纱并把纱绕在筒管上成一定形状的部\n件。 5.通\"茎\"。箭头后部插入箭杆的部分。也指剑身后部连接剑柄的部分。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铤"},{"id":"glyph-seal-94e8","script":"seal","character":"铨","reading":"quán","description":"指古代史书中解说、评议一类的文字\n称量;衡量;鉴别\n⒈秤，衡量轻重用～。～度。\n⒉旧时称盐官吏～选。～授。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铨"},{"id":"glyph-seal-94e9","script":"seal","character":"铩","reading":"shā","description":"长刃矛,古代的一种兵器\n铍有镡\n摧残;伤害\n⒈〈古〉一种长刃矛。\n⒉摧残，伤残。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铩"},{"id":"glyph-seal-94eb","script":"seal","character":"铫","reading":"yáo；diao","description":"儿;药铫儿\n一种带柄有嘴的小锅\n大锄\n⒈〈古〉一种大锄。\n铫qiāo 1.通\"?\"。锹锸之类。\n铫tiáo 1.矛。 2.见\"铫?\"。\n铫yào 1.见\"铫弋\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铫"},{"id":"glyph-seal-94ec","script":"seal","character":"铬","reading":"gè","description":"一种蓝白色多价金属元素,原子序数24,通常制得的铬,质硬且脆,抗腐蚀,只以化合状态存在。主要以铬铁矿形式存在,用铝热法、硅热法或电解法将它从矿石中分离出,主要用于\n米。\n【铬钢】含铬的合金钢，质地坚硬，耐磨、耐腐蚀，不生锈，可用来制造机器和工具。\n【铬镍钢】含铬、镍的合金钢，机械强度高，硬度和韧性大，耐热，耐腐蚀，用于制造飞机、汽车、拖拉机等的重要机件。\n【铬镍矿】铬和铁的氧化物，是主要的含铬矿石≮褐色，多是粒状、块状或豆状，是重要的冶金原料，又供制颜料。\n铬gé钩。兵器。\n铬luò剃发。\n铬gè金属元素，符号cr。银灰色结晶体，质硬而脆，是制造不锈钢﹑高速钢等的重要原料。在别种金属上镀铬可以防锈。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铬"},{"id":"glyph-seal-94ed","script":"seal","character":"铭","reading":"míng","description":"牢记不忘\n铭心立报,永矣无贰。\n⒈刻写在器物上记述生平、事业或警语等的文字鼎～。墓志～。座右～。\n⒉在器物上刻字～刻。也〈喻〉深刻记住～记在心。\n⒊文体的一种陋室～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铭"},{"id":"glyph-seal-94ee","script":"seal","character":"铮","reading":"zhēng","description":"铮zhèng 1.方言。形容器物表面光亮耀眼。参见\"铮亮\"﹑\"铮明互亮\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铮"},{"id":"glyph-seal-94f2","script":"seal","character":"铲","reading":"chǎn","description":"铲子\n古兵器。形似铲\n削平;铲除\n②用锹或铲摄取或清除～垃圾。\n【铲球】足球运动中倒地抢截球的技术。一般用在对手带球或接球越过自己，来不及用其他方法拦截的情况下。\n⒈削平或撮取东西的工具铁～子。锅～儿。\n⒉使用锹或铲～煤。将土～平。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铲"},{"id":"glyph-seal-94f6","script":"seal","character":"银","reading":"yín","description":"银制的器物\n⒈ 化学元素，金属，白色有光泽。符号ag。质柔软，富延伸性，是导热、导电的良好导体。在空气中不易氧化。可制硬币、器具等。\n⒉［银子］旧时以银鋳成块状的一种货币。\n⒊［银行］办理储蓄、放款、汇兑等业务的机构。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-银"},{"id":"glyph-seal-94f8","script":"seal","character":"铸","reading":"zhù","description":"造就","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铸"},{"id":"glyph-seal-94fa","script":"seal","character":"铺","reading":"pù","description":"铜器名。豆属。其上为一平的直壁浅盘。铺与豆的区别在于它没有细长的把柄,在盘下连铸一较宽的高圈足\n把东西展开或摊平\n⒈商店店～。饭～子。杂货～儿。\n⒉床床～。搭个～。\n⒊旧时指驿站。现多用于地名十里～。\n⒈陈设，展开，摊平摆置～设。～开。～平。～纸。～轨。平～直叙。\n⒉门环的底座金～交映。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-铺"},{"id":"glyph-seal-94fb","script":"seal","character":"铻","reading":"wú；yǔ","description":"wú：用于“锟铻”，古代传说中的宝剑名。yǔ：用于“鉏铻”，有抵触、不合之义。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-94fe","script":"seal","character":"链","reading":"liàn","description":"链条\n用索环栓住、捆绑或联接\n⒈用金属环连套构成的长条铁～子。表带～。\n⒉海洋上计算距离的一种单位，一～为十分之一海里，合185.2米。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-链"},{"id":"glyph-seal-9500","script":"seal","character":"销","reading":"xiāo","description":"溶化;消融\n通消”。清失;消除;\n⒈熔化金属，泛指熔化～金。～炼。\n⒉除去，解除～假。撤～。\n⒊售，出卖供～。推～。畅～。\n⒋消费开～。\n⒌通\"消\"。消失，消灭～声匿迹。\n⒎将销子推上把窗子～好。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-销"},{"id":"glyph-seal-9501","script":"seal","character":"锁","reading":"suǒ","description":"一种用铁环钩连而成的刑具\n链子\n⒈安在门、箱、柜等的开合处，使人不能随便打开的器具铁～。弹子～。\n⒉用锁锁住～门。～好箱子。\n⒊封闭封～。\n⒋链子～链。枷～。\n⒌紧皱眉头双眉深～。\n⒍一种缝纫法，针脚密，线斜交或钩连，多用于衣物边沿上～边。～扣眼。\n⒎像锁的东西石～。金～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锁"},{"id":"glyph-seal-9509","script":"seal","character":"锉","reading":"cuò","description":"用钢制成的磨铜、铁等表面的或竹本的满布细突起的工具\n用锉刀磨平、磨光、切断\n挫折;挫伤\n①锉刀。\n②用锉刀锉。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锉"},{"id":"glyph-seal-9510","script":"seal","character":"锐","reading":"ruì","description":"精锐的军队或士卒\n锐气,勇往直前的气势\n力量,劲\n锐利的兵器\n锋利\n长其尾\n⒉感觉灵敏敏～。目光～利。\n⒊勇往直前的气势～气。～不可当。\n⒋急剧，骤然～增。～变。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锐"},{"id":"glyph-seal-9511","script":"seal","character":"锑","reading":"tī","description":"三价和五价类金属元素,通常是金属银白色结晶,脆且有点软\n由锑衍生的一价离子sbh4+或基sbh4,已知仅以有机衍生物的形式存在\n锑tī金属化学元素之一。符号sb。银白色，有光泽，质硬而脆。它与铅及锡的合金可制铅字用于印刷，锑化铟是一种重要的半导体材料。\n锑tí 1.见\"鎕锑\"。 2.通\"蒂\"。筑土的杵。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锑"},{"id":"glyph-seal-9512","script":"seal","character":"锒","reading":"láng","description":"锒铛\n锒铛入狱\n锒láng［锒铛］\n①铁锁链。\n②锁链等金属撞击时所发出的声音。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锒"},{"id":"glyph-seal-9519","script":"seal","character":"错","reading":"cuò","description":"互相磨擦\n①参差；错杂犬牙交～。\n②物体相对摩擦～牙。\n③相对行动时避开而不碰上～车。\n④使办事的时间不冲突～开上下班时间。\n⑤不正确的～话、～字。\n⑥过错；错处我说的设～。\n⑧在凹纹中镶上或涂上金、银等～金。\n⑨打磨玉石的石头。\n⑩打磨玉石攻～。\n【错爱】谦辞。表示感谢对方爱护。\n【错别字】错字和别字的总称。\n【错愕】仓促惊讶；惊愕。\n【错金银】器物上的金银纹饰。镶金丝或金片的称错金，镶银片或银丝的称错银。在春秋时期已用于青铜器。\n【错落】交错纷杂～有致。\n【错综复杂】形容形势或情况纵横交叉，非常复杂。\n膳毋悖。\"郭沫若等集校﹕\"古本'错'作'醋'，刘本﹑朱东光本同。\"一说设置，安置。集校又引张文虎曰﹕\"'错'犹置也，下文云'凡置彼食'是也。朱本讹为'醋'。\" 7.通\"促\n\"。仓促，急迫。参见\"错愕\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-错"},{"id":"glyph-seal-951c","script":"seal","character":"锜","reading":"qí","description":"古代有三足的釜；也指古代一种凿木工具。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9521","script":"seal","character":"锡","reading":"xī","description":"素符号sn\n通緆”。细麻布\n和尚所用锡杖的简称\n通赐”。给予;赐给\n申锡无疆,\n⒈金属化学元素之一。符号sn。银白色，有光泽，质软，富于延伸性，在空气中不易起变化。用于制马口铁、青铜焊料、软管等。\n⒉通\"赐\"。赏赐，赐给。\n锡tì 1.假发。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锡"},{"id":"glyph-seal-9522","script":"seal","character":"锢","reading":"gù","description":"禁闭;禁锢\n⒈将金属熔化，浇灌阻塞空隙～漏锅。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锢"},{"id":"glyph-seal-9524","script":"seal","character":"锤","reading":"chuí","description":"八铢\n十二两\n六铢\n槌子,俗称榔头\n古兵器名。柄的上头有一个金属圆球\n秤砣\n锤形物\n①古代兵器。柄上有一个金属圆球。\n②像锤的东西秤～。\n③敲打东西的用具铁～、钉～。\n④用锤子敲打千～百炼。\n【锤炼】\n①磨练。\n②努力钻研，反复加工精心～。\n⒈秤上平衡重量的金属块秤～。\n⒉敲击东西的工具木～子。铁～儿。\n⒊用锤敲击～打。千～百炼。\n⒋像锤的东西纺～。钟～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锤"},{"id":"glyph-seal-9525","script":"seal","character":"锥","reading":"zhuī","description":"形如尖锥的东西\n⒈一端尖锐可钻孔的工具圆～子。\n⒊用锥形的东西钻在这儿～个孔。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锥"},{"id":"glyph-seal-9526","script":"seal","character":"锦","reading":"jǐn","description":"古指锦袍\n旧时书信中的敬词\n⒈带有彩色花纹的丝织品蜀～。～旗。～标。～绣。～缎。\n⒉色彩鲜艳华丽～霞。～羽。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锦"},{"id":"glyph-seal-952d","script":"seal","character":"锭","reading":"dìng","description":"膏灯\n金属大铸块\n块状物\n纺车或纺纱机上绕纱的尖头圆杆\n做成块状的药物\n计量金、银、墨等物的单位\n锭剂\n①锭子。纺车或纺纱机上绕纱的机件。\n③量词。用于成锭的东西一～墨。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锭"},{"id":"glyph-seal-952e","script":"seal","character":"键","reading":"jiàn","description":"车辖。安在车轴两端,管住车轮不脱离轴的铁棍\n钥匙\n竖着插的门闩\n⒈车轴上的铁条，用以管住车轮。又叫\"辖\"。\n⒉插在门上，用以关锁门户的金属棍子。\n⒊琴、电脑、发报机等物上可以按动的部分～盘。\n⒋〈古〉称钥匙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-键"},{"id":"glyph-seal-952f","script":"seal","character":"锯","reading":"jù；jv","description":"锯形物\n古刑具\n用锯子切割\n⒈能断木、石、金属等的一种工具。用钢片或钢条制成木～。电～。\n⒉用锯断物～树枝。～钢管。\n锯jū 1.用锔子补接器物。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锯"},{"id":"glyph-seal-9531","script":"seal","character":"锱","reading":"zī","description":"锱铢\n锱zī〈古〉重量单位。一说\"六铢\"为\"一锱\"，\"四锱\"为\"一两\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锱"},{"id":"glyph-seal-9532","script":"seal","character":"锲","reading":"qiè","description":"假借为洯”。用刀子刻\n⒉截断。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锲"},{"id":"glyph-seal-9534","script":"seal","character":"锴","reading":"kǎi","description":"好铁\n铁的别称\n锴kǎi好铁。多见于人名。\n锴jiē 1.精铁。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锴"},{"id":"glyph-seal-9538","script":"seal","character":"锸","reading":"chā","description":"铁锹,掘土的工具","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锸"},{"id":"glyph-seal-953b","script":"seal","character":"锻","reading":"duàn","description":"锤击\n罗织罪状,陷人于罪\n锻铁用的砧石\n锻 duàn把金属加热后锤打加工。\n【锻锤】金属压力加工用的机器，由动力带动锤头上下移动而产生压力。\n【锻铁】用生铁精炼而成，含碳量在0.15%以下。又称熟铁。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-锻"},{"id":"glyph-seal-9542","script":"seal","character":"镂","reading":"lòu","description":"金刚钻\n釜,烹饪用的锅\n通漏”。孔穴\n雕刻\n镂lǘ 1.属镂。剑名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镂"},{"id":"glyph-seal-9547","script":"seal","character":"镇","reading":"zhèn","description":"安定～静。～定。\n军事上重要的地方边防重～。\n中国县以下的行政区划单位。\n较大的集市城～。村～。\n把饮料等同冰或冷水放在一起使凉冰～。\n时常十年～相随。\n中国明、清两代军队的编制单位。\n姓。\n⒈压，压制，慑住～尺。～纸。～压。～慑。～住。\n⒉安定～定。～静。～国家，抚百姓。\n⒊守住，用兵驻守～守。坐～。\n⒋较大的集市村～。乡～。市～。\n⒌将饮料等与冰或冷水放在一起使凉冰～汽水。\n⒍通\"整\"。整段时间，时常～日。～相随。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镇"},{"id":"glyph-seal-954c","script":"seal","character":"镌","reading":"juān","description":"用凹线、凹面或点雕刻\n喻深刻记住\n降低;减少\n降职\n镌刻\n⒈凿，开掘可～。〈引〉刻，雕刻～板。～碑文。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镌"},{"id":"glyph-seal-954f","script":"seal","character":"镏","reading":"liú","description":"同刘”。杀戮\n镏金\n镏金\n镏liù〈方〉","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镏"},{"id":"glyph-seal-9550","script":"seal","character":"镐","reading":"gǎo","description":"镐头\n镐京。古都名。西周国都,在今陕西西安西南\n通皓”。光明的样子\n⒈一种刨土工具十字～。\n⒈镐京，西周的国都。在今陕西省长安之西北。\n⒉见gǎo。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镐"},{"id":"glyph-seal-9556","script":"seal","character":"镖","reading":"biāo","description":"旧式投掷暗器。通作镳”。一端较重有尖,像长枪的头\n标枪,多用木或竹杆为柄,铁镞\n镖 biāo旧式一种投掷武器。形状如长矛的尖端飞～。\n【镖客】旧时给行旅或运输中的货物保镖的人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镖"},{"id":"glyph-seal-9557","script":"seal","character":"镗","reading":"táng","description":"钟鼓的声音或敲锣的声音\n镗 〈名〉\n加工零件内孔的一种方法\n镗 〈动〉\n用镗孔刀内旋切\n⒈像声词。打钟鼓或敲锣的声音。\n⒉乐器名。一种小锣，称\"～儿\"或\"小～儿\"。\n镗táng同\"搪\"。用泥土、涂料等抹涂。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镗"},{"id":"glyph-seal-9558","script":"seal","character":"镘","reading":"màn","description":"镘刀\n铜钱;钱钞\n涂饰\n镘板\n镘màn抹子，抹墙用的工具～子。也指抹墙～墙。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镘"},{"id":"glyph-seal-955b","script":"seal","character":"镛","reading":"yōng","description":"镛yōng大钟。〈古〉一种乐器。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镛"},{"id":"glyph-seal-955c","script":"seal","character":"镜","reading":"jìng","description":"其他光学用器\n⒈镜子，反映形象的器具。古用铜磨制，今用玻璃涂水银制成铜～。圆～子。穿衣～。〈喻〉取鉴的人或事以人为～。\n⒉使用光学原理制成的帮助视力或作科学实验等的器具眼～。放大～。电子显微～。天文望远～。三棱～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镜"},{"id":"glyph-seal-955d","script":"seal","character":"镝","reading":"dí","description":"稀土族的三价金属元素,它形成的化合物属于已知的具有最大磁性的物质之列。其氧化物呈白色,而盐呈微黄色\n镝dí 1.箭头;箭。\n镝dī 1.金属元素。符号dy。是稀土元素之一。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镝"},{"id":"glyph-seal-955e","script":"seal","character":"镞","reading":"zú","description":"形容箭的轻捷,应声而至\n镞zú箭头箭～。\n镞chuò 1.一种小型锄。亦指一种锄法。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镞"},{"id":"glyph-seal-9560","script":"seal","character":"镠","reading":"liú","description":"成色好的黄金。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9561","script":"seal","character":"镡","reading":"tán；xin","description":"宝剑的剑鼻，剑柄和剑身连接处的两旁突出部分。亦称剑口”、剑环”。\n古代兵器，似剑而狭小。\n姓。\n镡xín 1.剑柄末端的突起部分，状如蕈类，中空，上有孔，吹而有声。也称剑首﹑剑珥﹑剑鼻。 2.指刀﹑剑之柄与刀﹑剑之身连接处的两旁突出部分。 3.因喻险要地势。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镡"},{"id":"glyph-seal-9562","script":"seal","character":"镢","reading":"jué","description":"镢头,刨土用的一种农具\n镢jué 1.镢头。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镢"},{"id":"glyph-seal-9563","script":"seal","character":"镣","reading":"liào","description":"有孔炉\n套在脚腕上使不能快跑的刑具","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镣"},{"id":"glyph-seal-9566","script":"seal","character":"镦","reading":"duì；dun","description":"矛戟柄末的平底金属套。同錿”\n冲压金属板,使其变形。不加热叫冷镦”,加热叫热镦”\n阉割\n镦短，镦粗\n镦宽\n镦 duì矛戟柄下端的平底金属套。又见dūn。\n镦 dūn冲压加工金属板。又见duì。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镦"},{"id":"glyph-seal-956b","script":"seal","character":"镫","reading":"dèng","description":"古代盛熟食器皿\n马镫\n古同灯”\n镫子\n出了大门,跳上战马,镫子一磕,飞奔而去\n镫 dèng挂在鞍子两旁供脚登的东西。多用铜铁制成。\n镫dēng 1.本作\"登\"。瓦豆。古代陶制的食器，形似高足盘，或有盖。 2.指这种食器的基部。 3.膏镫。也称锭﹑钉﹑烛豆﹑烛盘。古代照明用具。青铜制，上有盘，中有柱\n，下有底。或有三足及柄。盘所以盛膏，或中有锥供插烛。 4.泛指灯﹔油灯。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镫"},{"id":"glyph-seal-956c","script":"seal","character":"镬","reading":"huò","description":"形如大盆,用以煮食物的铁器\n指烹人的刑具\n锅子\n⒈〈古〉大锅。镬与鼎常用作残酷的刑具。\n⒉〈方〉锅铁～子。～子盖。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镬"},{"id":"glyph-seal-956f","script":"seal","character":"镯","reading":"zhuó","description":"钟状的铃,古代军中乐器\n镯子\n镯子\n玉镯子\n⒈套在手腕、手臂或脚胫上的一种圆环形装饰品手～子。\n⒉〈古〉军中的一种乐器。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镯"},{"id":"glyph-seal-9570","script":"seal","character":"镰","reading":"lián","description":"锋利的棱角\n镰刀\n镰尾","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镰"},{"id":"glyph-seal-9573","script":"seal","character":"镳","reading":"biāo","description":"借指马\n古代兵器。同镖”\n镳biāo 1.马嚼子。与衔合用，衔在口中，镳在口旁。青铜制或铁制，也有用骨﹑角制的上面可系銮铃。 2.指乘骑。 3.见\"镳镳\"。 4.同\"镖\"。参见\"镳局\"﹑\"镳客\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镳"},{"id":"glyph-seal-9575","script":"seal","character":"镵","reading":"chán","description":"一种锐利的器具；也有刺、凿的意思。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9576","script":"seal","character":"镶","reading":"xiāng","description":"铸铜铁器模型的瓤子\n古兵器名\n镶嵌物相嵌或相配合\n俗称修补其缺处\n如镶牙\n⒈将东西嵌进去或在外周加边～嵌。～牙。～金。～边。\n⒉马带上面的玉饰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-镶"},{"id":"glyph-seal-957f","script":"seal","character":"长","reading":"cháng；zhǎng","description":"cháng：长度大，与短相对；时间久；长处。zhǎng：生长；年纪较大；负责人，如长者、校长。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-95e8","script":"seal","character":"门","reading":"mén","description":"房屋、围墙、车船\n⒈建筑物的进出口，设在进出口能开关的装置，泛指进出口前～。城～。洞～。飞机～。\n⒉形状或作用像门的炉～。球～。电～。\n⒊诀窍，途径，方法窍～。入～。找～路。\n⒋家，家族一～大小。双喜临～。灭～之祸。\n⒍分类～类。分～别类。\n⒏量词三～大炮。四～课程。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-门"},{"id":"glyph-seal-95ea","script":"seal","character":"闪","reading":"shǎn","description":"忽有忽无, 突然显现\n⒈天空的电光～电。〈引〉突然一亮～亮。灯光一～。\n⒉转侧身体躲避～开。躲～。\n⒊动作过猛或颠扑，以致扭伤～了脚。\n⒋光亮不定或晃动或忽明忽暗～动。～烁。～耀。\n⒌光辉耀眼，光芒四射～金光§星～ ～亮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闪"},{"id":"glyph-seal-95ed","script":"seal","character":"闭","reading":"bì","description":"泛指闭合,合拢\n①关；合～嘴、～眼。\n②堵住；阻塞不通～气、交通～塞。\n③停止；结束～幕、～会。\n④姓。\n【闭关锁国】闭关自守，不跟外国往来。\n【闭关自守】关闭关口，不跟外人往来。也比喻与外界隔绝，不接受外界事物的影响。\n【闭管式循环】血液始终在心脏和血管内按一定方向流动的循环方式。\n【闭果】干果的一类。果实成熟时，果皮失水干燥，但不开裂。瘦果、坚果、翅果等都属闭果。\n【闭合电路】电荷通过的整个电路。即从电源正极出发，经内、外电路又回到电源的正极的路径。又称全电路。\n【闭合电路欧姆定律】闭合电路中的电流强度跟电源的电动势成正比，跟内、外电路的电阻之和成反比。\n【闭合环流】大气运动在地面与高空形成的一个个闭合的大气活动中心。在海平面气压图上表现为永久性和半永久性活动中心，对流层中、上层则以西风环流为主要特点。\n【闭合系统】与外界有热和功交换而无质量交换的系统。\n【闭路电视】一种图像通信系统。其信号从源点只传给预先安排好的与源点相通的特定电视机。广泛用于大量不同类型的监视工作、教育、电视会议等。\n【闭门羹】拒绝客人进门叫做让客人吃闭门羹。也指找人时无人在家昨晚去找他，吃了个～。\n【闭门思过】关着门独自反省自己的过错。\n【闭门造车】关上门造车。比喻做事不考虑客观情况，脱离实际。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闭"},{"id":"glyph-seal-95ee","script":"seal","character":"问","reading":"wèn","description":"⒈不知的或不明白的请人解答请～。询～。去～明白。\n⒉审讯，查究，惩办～案。～罪。胁从不～。\n⒊管，追究，考察，干预过～。这件事你要亲自去～。\n⒋安慰，慰劳～候。慰～。\n①要求回答或解释的题目。\n②需要研究讨论或尚待解决之事遗留～题。\n③关键或重要之点～题所在。\n④事故或意外那辆汽车出～题了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-问"},{"id":"glyph-seal-95ef","script":"seal","character":"闯","reading":"chuǎng","description":"孟浪行事\n奔走谋生\n开辟\n①猛冲一头～进来、横冲直～。\n②经受实际的考验或锻炼经过几年的风风雨雨，他早～出来了。\n【闯荡】指离开故乡外出谋生～江湖。\n【闯江湖】旧时指奔走他乡，以算卦、表演杂耍、卖药治病等职业为生。\n【闯将】原指敢于冲锋陷阵的将领，后多用于非战争场合科学种田的～。\n⒈猛冲，敢干～入。～将。敢～。有股～劲。\n⒉奔走，浪游谋生，经历锻炼走南～北。～荡江湖。他～出了自己的路。\n⒊招惹～祸。～了乱子。\n闯chèn 1.出头貌。 2.探头观望。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闯"},{"id":"glyph-seal-95f0","script":"seal","character":"闰","reading":"rùn","description":"为协调历年与天文周期而增加的日或月，如闰日、闰月、闰年。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-95f1","script":"seal","character":"闱","reading":"wéi","description":"后妃居处\n父母居室\n妇女居室\n科举时代对考场、试院的称谓\n⒈宫中的小门。又指庙门～门。\n⒉科举时代指考场入～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闱"},{"id":"glyph-seal-95f2","script":"seal","character":"闲","reading":"xián","description":"马厩,关养马的地方\n伦理道德的规范、界限\n⒈没有事做空～。清～。～白了头。\n⒉放着，不使用～着。～置。\n⒋与正事无关～话。～人勿进。\n闲jiàn 1.空隙;缝隙。 2.指空子，可乘的机会。 3.嫌隙，隔阂。 4.阻隔;间隔。 5.差别;距离。 6.间杂，夹杂。 7.离间。 8.间谍。 9.伺候;侦伺。 10.私下\n闲jiān 1.中间;内。亦指事物两者的关系。 2.一定的空间或时间里。 3.一会儿;顷刻。 4.近来。 5.量词。房室单位。有时也指学校﹑工厂﹑商店等的单位。 6.量词\n。格﹑片﹑瓣。 7.量词。指动作次数。\n闲jiǎn 1.通\"简\"。检阅，视察。 2.通\"简\"。简省。 3.用同\"涧\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闲"},{"id":"glyph-seal-95f3","script":"seal","character":"闳","reading":"hóng","description":"通宏”。大,宏大\n①〈形〉宏大，宽广\"～大广 博。\" │ ～达。\n②〈名〉姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闳"},{"id":"glyph-seal-95f4","script":"seal","character":"间","reading":"jiān","description":"中间;内\n一会儿,顷刻\n⒈夹缝门～窥视。\n⒉当中，两种事物之中或相互的关系中～。两山之～。朋友之～。\n⒊一定的时期、地方或人群等范围时～。午～。地～。大人～。\n⒋房屋，屋子房～。洗澡～。\n⒌量词，多指房屋两～房子。三～店铺。安得广厦千万～。\n⒈空隙工作～隙。\n⒉隔开，不连结～隔。～断。〈引〉断断续续地时时而～进。\n⒊隔阂，疏远亲密无～。〈引〉离间赵王信秦之～。\n⒋更迭寒热～作。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-间"},{"id":"glyph-seal-95f5","script":"seal","character":"闵","reading":"mǐn","description":"同悯”。怜恤,哀怜\n勉。黾勉\n忧虑\n⒈忧患，凶丧～凶。\n闵mín 1.见\"闵天\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闵"},{"id":"glyph-seal-95f7","script":"seal","character":"闷","reading":"mèn","description":"气闷,因气不通畅而引起的不快之感\n沉默不出声或声音不响的样子\n密闭,使不透气\n呆在家里不出门\n过饱\n昏闷;失去知\n⒈气压低或空气不流通等引起的不舒服～气。～热。\n⒉不出门～在家里。\n⒊紧闭，不让出气刚泡的茶～一～再喝。\n⒋不出声或声音不响亮～声不响。～声～气。\n⒈心烦，不畅快烦～。～ ～不乐。\n⒉密封的～罐。～葫芦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闷"},{"id":"glyph-seal-95f8","script":"seal","character":"闸","reading":"zhá","description":"水闸\n制动器的通称\n电闸,在电路上用来接通、断开或转换电流的装置\n把水截住,关闸。引申为拦\n⒈拦阻水流的建筑物，可随时开关，调节水量～门。排洪～。\n⒉使机器减速或停运的制动器车～。电～。\n⒊铁路上的转辙器。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闸"},{"id":"glyph-seal-95f9","script":"seal","character":"闹","reading":"nào","description":"渐不喜闹\n热闹\n浓盛\n⒈人多声音杂乱～市。热～。\n⒉吵，喧哗，搅扰～翻了。～得可欢。无理取～。\n⒊戏耍，玩笑～着玩的。\n⒋发生～水灾。\n⒌发作～情绪。\n⒍干，搞，弄～春耕。～革新。～清情况。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闹"},{"id":"glyph-seal-95fa","script":"seal","character":"闺","reading":"guī","description":"内室\n⒈上圆下方的小门。\n⒉旧称女子居住的卧室或内室～房。深～。\n①未结婚的女子。\n②女儿。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闺"},{"id":"glyph-seal-95fb","script":"seal","character":"闻","reading":"wén","description":"⒈听耳～目睹。～过则喜。～风而起。\n⒉消息，听说的，听见的新～。奇～。～所未～。\n⒊出名，有名望～人。～名。\n⒍用鼻子嗅～着烟味。～到香味。\n闻wèn 1.声誉，名声。 2.通\"问\"。慰问。 3.通\"问\"。询问。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闻"},{"id":"glyph-seal-95fc","script":"seal","character":"闼","reading":"tà","description":"门内\n门楼上的小屋","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闼"},{"id":"glyph-seal-95fd","script":"seal","character":"闽","reading":"mǐn","description":"五代十国之一\n闽mǐn福建省的简称。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闽"},{"id":"glyph-seal-95fe","script":"seal","character":"闾","reading":"lǘ；lv","description":"里巷\n⒈〈古〉一种居民组织，五家为比，五比为～。\n⒉里巷的门倚～而望。\n⒊里巷穷～漏屋。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闾"},{"id":"glyph-seal-95ff","script":"seal","character":"闿","reading":"kǎi","description":"闿（阦）kǎi\n⒈开。\n⒉通\"恺\"。欢乐。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-闿"},{"id":"glyph-seal-9600","script":"seal","character":"阀","reading":"fá","description":"功劳\n名门巨室,仕宦人家\n依靠权势在某一方面有特殊支配地位的人物或集团\n阀门\n⒈〈古〉有权势有地位的家庭或家族名～之家。\n⒉〈古〉凭借权势、财力而拥有特殊地位的个人、家族或集团军～。财～。\n【阀阅】\n①〈古〉记载功绩或经历的簿籍。〈引〉功勋。\n②封建社会时代的贵族、官僚，大门外立两柱，左称\"阀\"，右称\"阅\"，用来张榜\"功状\"。因而又称他们为\"阀阅之家\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阀"},{"id":"glyph-seal-9601","script":"seal","character":"阁","reading":"gé","description":"门限\n一种架空的小楼房,中国传统建筑物的一种。其特点是通常四周设隔扇或栏杆回廊,供远眺、游憩、藏书和供佛之用\n⒈楼房的一种，一般两层，周围开窗，供游息、藏书等用亭台楼～。文渊～，在故宫。佛香～，在颐和园。\n⒉旧称女子的卧房闺～。\n⒊旧时宫中的政务机关，近代某些国家的最高行政机关内～。组～。～员。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阁"},{"id":"glyph-seal-9602","script":"seal","character":"阂","reading":"hé","description":"盖墙用的草帘子\n关闭\n阂hé阻碍，阻隔隔～。疑～。\n阂ài 1.从门外关门。 2.引申为遮闭。参见\"阂心\"。\n阂hài 1.藏;塞。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阂"},{"id":"glyph-seal-9604","script":"seal","character":"阄","reading":"jiū","description":"写上字或画上记号的小纸团,供赌胜负或决定事情时抓取\n拈阄,抓阄","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阄"},{"id":"glyph-seal-9605","script":"seal","character":"阅","reading":"yuè","description":"引申为计算\n察看;视察,考查\n检阅\n⒈看～读。～览。传～。已～。\n⒉察看～兵。检～。\n⒊经历～历。～世。～年余。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阅"},{"id":"glyph-seal-9606","script":"seal","character":"阆","reading":"láng","description":"门高大\n空旷\n隍,无水的城壕\n阆风巅的省称\n阆làng阆中县，在四川省。\n阆lǎng 1.宽大明亮。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阆"},{"id":"glyph-seal-9607","script":"seal","character":"阇","reading":"dū；shé","description":"dū：城门上的台。shé：用于“阿阇梨”，佛教对教师或僧人的尊称。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-9608","script":"seal","character":"阈","reading":"yù","description":"门槛\n泛指界限或范围\n门户;门口\n阈值\n阈yù门坎。〈引〉界限或范围～值。视～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阈"},{"id":"glyph-seal-9609","script":"seal","character":"阉","reading":"yān","description":"特指宦官\n阉割\n⒈阉割，割去生殖腺～鸡。～猪。～牛。\n⒉封建时代宫廷中的宦官、太监～宦。～人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阉"},{"id":"glyph-seal-960a","script":"seal","character":"阊","reading":"chāng","description":"阊阖\n阊门\n①神话传说中的天门。\n②皇宫的正门。\n阊tāng 1.鼓声。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阊"},{"id":"glyph-seal-960b","script":"seal","character":"阋","reading":"xì","description":"争吵，不和，如兄弟阋墙。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-960d","script":"seal","character":"阍","reading":"hūn","description":"宫门\n阉官之属\n⒈宫门谁能叫帝～？\n⒉守门的人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阍"},{"id":"glyph-seal-960e","script":"seal","character":"阎","reading":"yán","description":"阎yán里巷的门，又指里巷～里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阎"},{"id":"glyph-seal-960f","script":"seal","character":"阏","reading":"è","description":"阻塞\n遏止;抑制\n门扇;闸板\n阏氏\n阏è 1.遏止;抑制。 2.堵塞。 3.门扇;闸板。\n阏yù 1.见\"阏与\"。 2.通\"淤\"。淤泥。\n阏yè 1.见\"单阏\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阏"},{"id":"glyph-seal-9610","script":"seal","character":"阐","reading":"chǎn","description":"开辟;开拓\n讲明白\n发扬,发展与提倡\n阐 chǎn说明；讲明白～明、～述。\n【阐明】讲明；说明文章～了物体运动的规律。\n【阐扬】说明并宣扬～我国的对外政策。\n⒈说明，表明～明。～发。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阐"},{"id":"glyph-seal-9611","script":"seal","character":"阑","reading":"lán","description":"环状物\n印刷页纸上的分行线条\n⒈晚，深岁～。夜～人静。\n⒉［阑干］\n①纵横交错的样子玉容寂寞泪～干。\n②也作\"栏杆\"，用竹、木、铁、石等制成的遮挡物石～干。铁～干。桥～杆。\n⒊残尽酒～。［阑珊］将尽，衰落的样子诗情酒兴渐～珊。\n⒋混进，擅自出入～入。～出。\n⒌同\"拦\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阑"},{"id":"glyph-seal-9612","script":"seal","character":"阒","reading":"qù","description":"寂静\n空虚\n阒寂\n阒寂的原野\n阒然\n庭园阒然\n阒qù寂静～无一人。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阒"},{"id":"glyph-seal-9614","script":"seal","character":"阔","reading":"kuò","description":"宽横的距离大\n有江千里阔。╠\n⒈宽广宽～。广～。辽～〓～三十里。〈引〉时间或距离长～别五十年。\n⒉疏略，不切实～略。迂～。\n⒊宽缓，放宽～其租赋。\n⒋富有的，奢侈的～人。～气。～绰。摆～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阔"},{"id":"glyph-seal-9615","script":"seal","character":"阕","reading":"què","description":"尽;无剩余\n旧指服丧期满\n乐终\n⒉量词指词或歌曲歌两～。\n阕kuí 1.戟类兵器。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阕"},{"id":"glyph-seal-9616","script":"seal","character":"阖","reading":"hé","description":"盖墙用的草帘子\n关闭\n⒊閤hé\n⒈关闭～门。\n⒉门扇，门板修～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阖"},{"id":"glyph-seal-9617","script":"seal","character":"阗","reading":"tián","description":"充满;填塞\n阗咽","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阗"},{"id":"glyph-seal-9619","script":"seal","character":"阙","reading":"què；jue","description":"去除\n挖掘\n毁伤\n缺点;错误\n豁口,空缺\n指待补的官额。即缺额\n⒈缺点，过错～失。\n⒈皇宫前面两边的楼台，中间有道路。\n⒉宫殿宫～。\n⒊墓道前两边的石碑坊。\n阙jué 1.除去;失去。 2.侵损;削减。 3.通\"掘\"。 4.通\"厥\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阙"},{"id":"glyph-seal-961a","script":"seal","character":"阚","reading":"kàn","description":"探望,看望\n古地名\n⒈老虎声，虎怒吼。\n⒉见kàn、xiàn。\n⒈姓。\n⒉见hǎn。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阚"},{"id":"glyph-seal-961c","script":"seal","character":"阜","reading":"fù","description":"fù：(1)土山高～。如山如～。\n(2)盛，多，大物～民丰。民殷财～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阜"},{"id":"glyph-seal-961f","script":"seal","character":"队","reading":"duì","description":"坠落\n队列\n军队或集体的编制单位\n①行列排～、整～。\n②集体的编制单位生产～、球～。\n③特指少年先锋队～旗。\n④量词。\n【队礼】中国少年先锋队队员行的礼。右手五指并拢，手掌向前，高举头上，表示人民利益高于一切。\n【队日】少年先锋队举行集体活动的日子，除假期外一般每周一次。\n队zhuì 1.坠落◇作\"坠\"。 2.指倒翻。 3.引申为低沉。 4.殒灭;丧失。\n队suì 1.隧道。 2.泛指道路。 3.特指险道﹑要道。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-队"},{"id":"glyph-seal-9621","script":"seal","character":"阡","reading":"qiān","description":"qiān：(1)田间的小路～陌。\n(2)通往坟墓的道路～表（墓碑）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阡"},{"id":"glyph-seal-962a","script":"seal","character":"阪","reading":"bǎn","description":"bǎn：(1)同坂”。\n(2)崎岖硗薄的地方～田。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阪"},{"id":"glyph-seal-962e","script":"seal","character":"阮","reading":"ruǎn","description":"ruǎn：姓。\n〔～咸〕一种弦乐器，柄长而直，略象月琴，四根民弦，现亦有三根弦的。传说因中国晋代人阮咸善弹此乐器而得名。简称阮”。\n〔大小～〕中国晋代阮籍和他的侄儿阮咸并有盛名，同为竹林七贤”，世称大小阮”◇小阮”用作侄的代称，如贤阮”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阮"},{"id":"glyph-seal-9631","script":"seal","character":"阱","reading":"jǐng","description":"jǐng：捕野兽用的陷坑陷～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阱"},{"id":"glyph-seal-9632","script":"seal","character":"防","reading":"fáng","description":"fáng：(1)戒备，预先作好应急的准备～止。～备。预～。～范（防备，戒备）。～患未然。～意如城（指严格控制个人欲望，就像守城防敌一样）。～微杜渐（在坏事和错误刚冒头的时候就加以制止，以免发展下去）。\n(2)守卫～守。边～。～。\n(3)堤坝～堤。以～止水”。\n(4)抵得，相当百夫之～（抵得上百人的人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-防"},{"id":"glyph-seal-9633","script":"seal","character":"阳","reading":"yáng","description":"泰山之阳,汶水西流。\n⒈跟\"阴\"相对。〈古〉我国哲学家把一切事物概括为\"阴阳\"两个对立统一的范畴火为～，水为阴。背为～，胸为阴。胸为～，腹为阴。\n⒉指太阳～光。向～花。\n⒊明亮，温暖多～。\n⒋凸出的，外露的～文。～沟。～奉阴违。\n⒌带正电的～电。～极。\n⒎迷信者所谓\"属于活人与人世\"的～寿。～间。\n⒏男性生殖器～物。\n①显露出来的化验～性。\n②雄性，男性的。\n⒑〈古〉通\"佯\"。假装。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阳"},{"id":"glyph-seal-9634","script":"seal","character":"阴","reading":"yīn","description":"阴谷皆入济\n以胸腹而言，胸在上为阳，腹在下为～。以阴阳交错的变化，说明物质世界的运动和发展。\n⒉称月亮为\"太阴\"，简称\"阴\"月为～。～历。\n⒋云遮挡着太阳或月亮、星星～天。夕～。～雨。\n⒌光线被东西遮住所造成的影子～影。树～。\n⒍山的北面，水的南面居山之～『水之～。华～县，在陕西省华山之北。江～县，在江苏省长江之南。\n⒎带负电的～电。～极。\n⒏物体的背面碑～。\n⒐诡诈，不光明正大～谋诡计。～险毒辣。\n⒑女的，雌的或化验用语男为阳，女为～。～性反应。\n⒒生殖器或专指女性生殖器女～。\n⒓迷信者所谓\"属于鬼、神的\"～间、～宅等等都是虚构的。\n①天气低沉郁闷。\n②气氛不活跃。\n③忧郁、不开朗～郁不乐。\n阴yìn 1.覆荫;庇护。 2.埋藏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阴"},{"id":"glyph-seal-9636","script":"seal","character":"阶","reading":"jiē","description":"梯子\n⒉〈古〉官员的品级官～。\n①指同一阶级中因经济地位的不同而分成的层次农民阶级中有富农、中农、贫农等～层。\n②指由不同阶级出身，而因某种相同的特征所形成的集团知识分子～层。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阶"},{"id":"glyph-seal-963b","script":"seal","character":"阻","reading":"zǔ","description":"zǔ：(1)险要的地方马陵道狭，而旁多～隘，可伏兵”。\n(2)拦挡～挡。～隔。～拦。～力。～挠。梗～。劝～。～击。～抑。～滞。～难（nàn）。～塞（sè）。\n(3)艰难道～且长。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阻"},{"id":"glyph-seal-963f","script":"seal","character":"阿","reading":"ā","description":"ā：加在称呼上的词头～大。～爷。～爹。～罗汉。～毛。～婆。～弟。～姊。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-阿"},{"id":"glyph-seal-9642","script":"seal","character":"陂","reading":"bēi","description":"bēi：(1)池塘～塘。～池。千顷之～。\n(2)水边，水岸东海之～。\n(3)山坡，斜坡～南～北鸦阵黑，舍西舍东枫叶赤”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陂"},{"id":"glyph-seal-9644","script":"seal","character":"附","reading":"fù","description":"fù：(1)另外加上，随带着～体。～件。～带（ａ．另外有所补充的；ｂ．非主要的）。～庸。～会（ａ．把不相关连的事勉强拉到一起，如牵强～～”；ｂ．组织文章、布局谋篇、命意修辞等创作活动，如精思～～，十年乃成”）。～赘悬疣。\n(2)同意，赞同随声～和。～议。\n(3)捎带一男～书至”。\n(4)靠近～近。～耳低言。\n(5)依从依～。归～。趋炎～势。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-附"},{"id":"glyph-seal-9645","script":"seal","character":"际","reading":"jì","description":"泛指合缝的地方;缝隙\n边缘\n时候;时机\n去就之际\n⒈交界处，边缘处海～。天～。一望无～。\n⒉彼此之间省～。国～。厂～竞争。\n⒊时候或先后交接的时候胜利之～。夏秋之～。\n⒋当，适逢～此美景。\n⒌会合，交流刚柔～也。广泛交～。\n⒍到，接近～天接地。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-际"},{"id":"glyph-seal-9646","script":"seal","character":"陆","reading":"lù；liu","description":"数目字六”的大写\n水陆并进。\n路;道\n⒈\"六\"的大写。\n⒈高出水面的土地～地。～路。登～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陆"},{"id":"glyph-seal-9647","script":"seal","character":"陇","reading":"lǒng","description":"即陇山。绵延于陕西、甘肃交界的地方\n甘肃省的简称。因古为陇西郡地而得名\n通垄”。田埂\n泛指山","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陇"},{"id":"glyph-seal-9648","script":"seal","character":"陈","reading":"chén","description":"古国名\n陈朝\n战阵;行列\n陈设,陈列","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陈"},{"id":"glyph-seal-9649","script":"seal","character":"陉","reading":"xíng","description":"山脉中断的地方\n灶边承放器物处的形状、样子\n斜坡\n⒈山口，山脉中断的地方。\n⒉灶边放东西的土台。\n陉jìng 1.狭窄的通道。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陉"},{"id":"glyph-seal-964b","script":"seal","character":"陋","reading":"lòu","description":"lòu：(1)丑的，粗劣，不文明的丑～。粗～。～俗。\n(2)狭小，简略～室。简～。因～就简。～巷簟瓢（形容家境贫寒，生活清苦）。\n(3)见识小浅～。孤～寡闻。\n(4)轻视～今而荣古。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陋"},{"id":"glyph-seal-964d","script":"seal","character":"降","reading":"jiàng","description":"jiàng：(1)下落，落下下～。～旨。～临。～旗。空～。\n(2)减低，贬抑～低。～价。～职。～解（jiě）。～心相从（抵制自己心志以服从别人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-降"},{"id":"glyph-seal-9650","script":"seal","character":"限","reading":"xiàn","description":"xiàn：(1)指定的范围期～。界～。权～。局～。～额。\n(2)指定范围～制。～于。～期。～价（官方指定最高或最低价格，不得超越）。无～。\n(3)门槛门～。\n(4)险阻关～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-限"},{"id":"glyph-seal-9654","script":"seal","character":"陔","reading":"gāi","description":"gāi：(1)台阶，层次具泰一祠坛……三～”。\n(2)田间的土岗子。\n(3)指陔夏”（古乐章名）宾出，奏～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陔"},{"id":"glyph-seal-9655","script":"seal","character":"陕","reading":"shǎn","description":"古地名。战国陕邑,在今河南省陕县\n中国陕西省的简称\n狭窄","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陕"},{"id":"glyph-seal-965b","script":"seal","character":"陛","reading":"bì","description":"bì：宫殿的台阶～级。阶～。\n〔～下〕对国王或皇帝的敬称。\n〔～见〕谒见皇帝。\n〔～辞〕臣子向皇帝告别。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陛"},{"id":"glyph-seal-965f","script":"seal","character":"陟","reading":"zhì","description":"zhì：(1)登高～山。\n(2)晋升，进用黜～（指官吏的进退升降）。～罚臧否，不宜异同”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陟"},{"id":"glyph-seal-9662","script":"seal","character":"院","reading":"yuàn","description":"yuàn：(1)围墙里房屋四周的空地～子。～墙。庭～。\n(2)某些机关、学型公共场所名称法～。医～。戏～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-院"},{"id":"glyph-seal-9664","script":"seal","character":"除","reading":"chú","description":"chú：(1)去掉～害。～名。～根。铲～。废～。排～。～暴安良。\n(2)改变，变换岁～（农历一年的最后一天）。～夕。\n(3)不计算在内～非。～外。\n(4)算术中用一个数去分另一个数，是乘”的反运算～法。\n(5)台阶阶～。庭～。\n(6)任命官职～拜（授官）。～授。～书（授官的诏令）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-除"},{"id":"glyph-seal-9668","script":"seal","character":"陨","reading":"yǔn","description":"丧失,失去\n天诱其衷,成王陨命,穆公是以不\n陨yǔn从高处掉下，坠落～石。～星。\n陨yuán 1.周围;幅员。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陨"},{"id":"glyph-seal-9669","script":"seal","character":"险","reading":"xiǎn","description":"常石险远。\n地势险峻、危险\n⒈地势扼要，难于通过～要。～阻。天～。\n⒉地势不平坦～以远，则至者少。\n⒊危，不安全危～。冒～∶～。～症。～境。\n⒋狡诈，狠毒～诈。～恶。～毒。阴～。\n⒌几乎，差一点～遭暗算。～些丧命。\n险jiǎn 1.少。\n险yán 1.岩岸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-险"},{"id":"glyph-seal-966a","script":"seal","character":"陪","reading":"péi","description":"péi：(1)跟随在一起，在旁边做伴～伴。～同。～客。～葬。～嫁。失～。\n(2)从旁协助，辅佐～臣。～审。\n(3)增加的，非主要的～衬。～都。\n(4)古同赔”，偿还。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陪"},{"id":"glyph-seal-966c","script":"seal","character":"陬","reading":"zōu","description":"zōu：(1)隅，角落～见（粗浅的见识）。\n(2)聚居～落（村落，村庄）。\n(3)农历正月的别称～月。孟～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陬"},{"id":"glyph-seal-9672","script":"seal","character":"陲","reading":"chuí","description":"chuí：边疆，国境，靠边界的地方边～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陲"},{"id":"glyph-seal-9675","script":"seal","character":"陵","reading":"líng","description":"líng：(1)大土山山～。丘～。～谷迁变（简作陵谷”）。\n(2)高大的坟墓～园。～墓。～寝。\n(3)古同凌”，侵犯，欺侮。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陵"},{"id":"glyph-seal-9676","script":"seal","character":"陶","reading":"táo","description":"táo：(1)用黏土烧制的器物～俑。～粒。～瓷。～管。～器。\n(2)制造陶器～冶。～铸。\n(3)喻教育、培养～化。～育。～染。熏～。\n(4)快乐的样子，使快乐～然。～醉。～～。\n(5)古同淘”，洗。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陶"},{"id":"glyph-seal-9677","script":"seal","character":"陷","reading":"xiàn","description":"xiàn：(1)掉进，坠入，沉下～落。～没（mò）。～溺。～于。～入。\n(2)为捉野兽挖的坑～坑。～阱。\n(3)凹进双眼深～。\n(4)设计害人～害。诬～。～人于罪。\n(5)攻破，占领失～。沦～。\n(6)缺点缺～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-陷"},{"id":"glyph-seal-9685","script":"seal","character":"隅","reading":"yú","description":"yú：(1)角落城～。墙～。屋～。～隙（屋角的洞穴）。向～而泣。\n(2)靠边的地方海～。\n〔～中〕将近中午的时候。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隅"},{"id":"glyph-seal-9686","script":"seal","character":"隆","reading":"lóng","description":"lóng：(1)盛大，厚，程度深～冬。～重（zhòng）。\n(2)兴（xīng）盛兴～。～盛（shèng）。\n(3)高，高起～起。～穹。～准（高鼻梁）。\n(4)尊崇～师。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隆"},{"id":"glyph-seal-9688","script":"seal","character":"隈","reading":"wēi","description":"wēi：(1)山水等弯曲的地方山～。水～。城～。\n(2)角落隅～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隈"},{"id":"glyph-seal-968b","script":"seal","character":"隋","reading":"suí；duò","description":"suí：(1)中国朝代名～代。\n(2)姓。\nduò：(1)古代祭祀用的残肉和残食既祭，则藏其～”。\n(2)古同堕”，垂落。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隋"},{"id":"glyph-seal-968d","script":"seal","character":"隍","reading":"huáng","description":"huáng：没有水的城壕城～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隍"},{"id":"glyph-seal-968f","script":"seal","character":"随","reading":"suí","description":"⒈跟着，沿着，顺着～着。跟～。～波逐流。\n⒉顺从，任凭～意。～你的便。～遇而安。～心所欲。\n⒊顺便，顺手～手关灯。\n⒋即，立刻～即。～叫～到。\n①顺从附和别人的意见～和大伙意见。\n②指态度和气，不固执己见他一向很～和。\n随tuǒ 1.椭圆貌。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-随"},{"id":"glyph-seal-9690","script":"seal","character":"隐","reading":"yǐn","description":"藏匿;隐蔽\n则事可以隐定。\n⒈藏匿，潜伏，不显露～藏。～匿。～伏。～居。～患。\n⒉不明显，不清楚～痛。～约其辞。\n⒊不说出来，不让人知道～讳。～情。～瞒。\n隐yìn 1.依据;凭依。 2.筑，击。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隐"},{"id":"glyph-seal-9694","script":"seal","character":"隔","reading":"gé","description":"gé：(1)遮断～开。～离。～绝。～断。阻～。\n(2)相去有一段距离～壁。～年。～行（háng）。～岸观火（喻见人遇到困难，漠不关心，采取观望或看热闹的态度）。～墙有耳。\n(3)思想感情有距离～阂。～膜。～心。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隔"},{"id":"glyph-seal-9697","script":"seal","character":"隗","reading":"wěi；kuí","description":"wěi：(1)高峻的样子。\n(2)姓。\nkuí：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隗"},{"id":"glyph-seal-9698","script":"seal","character":"隘","reading":"ài","description":"ài：(1)险要的地方～口。要～。关～。险～。\n(2)狭窄～巷。～路。狭～。\n(3)穷～穷。～窘。贫～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隘"},{"id":"glyph-seal-9699","script":"seal","character":"隙","reading":"xì","description":"xì：(1)裂缝～罅（裂缝）。缝～。～大而墙坏。\n(2)感情上的裂痕～嫌。有～。仇～。\n(3)闲，空～地（空地）。农～。\n(4)机会，空子乘～。\n(5)际，接近北～乌丸、夫馀”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隙"},{"id":"glyph-seal-969c","script":"seal","character":"障","reading":"zhàng","description":"zhàng：(1)阻隔，遮挡～蔽。～翳。～碍。故～。～眼法。一叶～目，不见泰山。\n(2)中国秦、汉两代边塞上作防御用的城堡出五原塞数百里，远者千里，筑城～列亭，至庐朐”。\n(3)用作遮蔽、防卫的东西屏～。\n(4)古同幛”，画轴。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-障"},{"id":"glyph-seal-96b0","script":"seal","character":"隰","reading":"xí","description":"xí：(1)低湿的地方山有榛，～有苓”。\n(2)新开垦的田。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隰"},{"id":"glyph-seal-96b6","script":"seal","character":"隶","reading":"lì","description":"跟从;附属\n通离”。流离\n通肄”\n检查\n练习\n⒈附属，属于～属。直～中央。\n⒉封建时代的衙役、差役～卒。皂～。\n⒊旧时地位低、被奴役的人奴～。仆～。\n⒋一种汉字字体，相传是秦朝程邈所创造～书。\n隶dài 1.及;捕获◇作\"逮\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隶"},{"id":"glyph-seal-96bc","script":"seal","character":"隼","reading":"sǔn","description":"sǔn：鸟类的一科，翅膀窄而尖，上嘴呈钩曲状，背青黑色，尾尖白色，腹部黄色。饲养驯熟后，可以帮助打猎。亦称鹘”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隼"},{"id":"glyph-seal-96bd","script":"seal","character":"隽","reading":"jùn；juàn","description":"jùn：同俊”①。\njuàn：鸟肉肥美，味道好，引申为意味深长～永（指言语、诗文）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-隽"},{"id":"glyph-seal-96c0","script":"seal","character":"雀","reading":"què；qiāo；qiǎo","description":"què：鸟类的一科，吃粮食镣昆虫。特指麻雀”，泛指小鸟～跃（高兴得像雀儿那样跳跃）。～盲（即夜盲症”）。～斑。～噪（名声宣扬，含贬义）。\nqiāo：〔～子〕即雀斑”。\nqiǎo：义同（一），用于一些口语词～盲眼（即雀（què）盲”）。家～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雀"},{"id":"glyph-seal-96c1","script":"seal","character":"雁","reading":"yàn","description":"yàn：鸟类的一属，形状略像鹅，群居水边，飞时排列成行～行（háng）。～序。～阵（雁行整齐，如同军队布阵）。～过拔毛（喻为牟利不放过任何机会）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雁"},{"id":"glyph-seal-96c4","script":"seal","character":"雄","reading":"xióng","description":"xióng：(1)阳性的，与雌”相对～性。～鸡。～狮。～蕊。～蜂。\n(2)强有力的～壮。～健。～伟。～厚。～浑。～劲。～奇。～踞。～视。～姿。～心。～关。～图。～辩。～才大略。\n(3)强有力的人或国家～杰（ａ．才能出众的人；ｂ．才能出众）。～俊。英～。枭～。奸～。称～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雄"},{"id":"glyph-seal-96c5","script":"seal","character":"雅","reading":"yǎ","description":"yǎ：(1)正规的，标准的～言。～正（ａ．规范的；ｂ．正直；ｃ．客气话，用于赠给他人的书画题款上，请对方指正）。\n(2)美好的，高尚的，不粗俗的文～。高～。典～。～观。～教（jiào）。～兴（xìng）。～座。～俗。\n(3)平素，素来～爱。～善鼓琴。\n(4)极，甚～以为美。～不欲为。\n(5)交往无一日之～。\n(6)酒器名～量（liàng）（ａ．大的酒量；ｂ．宽宏的气度）。\n(7)中国周代朝庭上的乐歌风～颂。～声（泛指诗歌）。\n(8)古同鸦”，乌鸦。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雅"},{"id":"glyph-seal-96c6","script":"seal","character":"集","reading":"jí","description":"jí：(1)群鸟栖止于树上黄鸟于飞，～于灌木”。\n(2)聚合，会合聚～。～合。～会。～体。～团。～训。～散。～资。～中。～大成。～腋成裘。\n(3)会合许多著作编成的书～子。文～。诗～。选～。全～。\n(4)大型图书中可以相对独立的一部分，或一部小说、一部电影、电视剧中相对独立的段落上～。第五～。\n(5)定期交易的市场～市。赶～。\n(6)中国古代图书的四部分类法～部。经史子～。\n(7)成就，成功大业未～。\n(8)数学基本概念之一，指若干具有共同属性的事物的总体子～。交～。\n(9)古同辑”，和睦。\n(10)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-集"},{"id":"glyph-seal-96c7","script":"seal","character":"雇","reading":"gù","description":"gù：(1)出钱让人为自己做事～工。～主。～用。～员。～佣。～请。\n(2)租赁交通运输工具～车。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雇"},{"id":"glyph-seal-96c9","script":"seal","character":"雉","reading":"zhì","description":"zhì：(1)鸟，雄的羽毛很美，尾长；雌的淡黄褐色，尾较短。善走，不能久飞。肉可食，羽毛可做装饰品。通称野鸡”。\n(2)古代计算城墙面积的单位，长三丈高一丈为一雉。\n(3)城墙～堞。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雉"},{"id":"glyph-seal-96cc","script":"seal","character":"雌","reading":"cí","description":"cí：(1)母的，阴性的，与雄”相对～性。～花。～雄。\n(2)柔羽。\n〔～黄〕矿物，橙黄色，可做颜料，古时用来涂改文字，如信口～～”（随意讥评）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雌"},{"id":"glyph-seal-96cd","script":"seal","character":"雍","reading":"yōng","description":"yōng：(1)和谐。\n(2)古同壅”，遮蔽，壅塞。\n(3)古同拥”，拥有。\n(4)姓。\n〔～～〕ａ．鸟和鸣声，如～～鸣雁”；ｂ．乐声和谐，如听庙中之～～”。\n〔～容〕文雅大方，从容不迫的样子，如～～大雅”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雍"},{"id":"glyph-seal-96cf","script":"seal","character":"雏","reading":"chú","description":"引申为幼禽\n幼小的动物\n幼儿\n【雏形】\n①初步形成的规模。\n②照原形缩小后的模型。\n雏jù 1.人名用字。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雏"},{"id":"glyph-seal-96d2","script":"seal","character":"雒","reading":"luò","description":"luò：(1)古书上指白鬣的黑马。\n(2)古同烙”，烙印。\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雒"},{"id":"glyph-seal-96d5","script":"seal","character":"雕","reading":"diāo","description":"diāo：(1)鸟类的一属，大型猛禽，羽毛褐色，上嘴勾曲，视力很强，利爪，能捕食山羊、野兔等（亦作鹫”）～悍。一箭双～。\n(2)刻竹、木、玉、石、金属等木～。浮～。玉～。～版。～龙（指善于撰写文章）。～镌。～塑。～虫小技。\n(3)有彩绘装饰的～弓。～鞍。～青（在人体上刺花纹，涂上青色）。\n(4)同凋”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雕"},{"id":"glyph-seal-96e0","script":"seal","character":"雠","reading":"chóu","description":"校对文字\n同仇”。仇恨;仇怨\n同仇”。\n①同'仇'，\n②校对文字校～。\n⒈校对～校。～正。\n⒉应答。〈引〉应验不～。\n⒊售，卖出去酒～数倍。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雠"},{"id":"glyph-seal-96e8","script":"seal","character":"雨","reading":"yǔ","description":"从云中落向地面的水滴。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-96e9","script":"seal","character":"雩","reading":"yú","description":"yú：古代为求雨而举行的一种祭祀～祭。～禳（出雨消灾）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雩"},{"id":"glyph-seal-96ea","script":"seal","character":"雪","reading":"xuě","description":"xuě：(1)天空中飘落的白色结晶体，多为六角形，是天空中的水蒸气冷至摄氏零度以下凝结而成～花。～山。～中送炭（喻在别人遇到困难时及时给予帮助）。\n(2)洗去，除去报仇～恨。为国～耻。平反昭～。\n(3)擦拭晏子独笑于旁，公～涕而顾晏子”。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雪"},{"id":"glyph-seal-96f1","script":"seal","character":"雱","reading":"pāng","description":"雱pāng雪下得大的样子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雱"},{"id":"glyph-seal-96f6","script":"seal","character":"零","reading":"líng","description":"líng：(1)液体降落感激涕～。\n(2)植物凋谢～落。凋～。～散（sàn）。\n(3)整数以外的尾数～数儿。\n(4)部分的，细碎的，与整”相对～碎。～卖。～钱。～售。～乱。～工。～打碎敲。\n(5)整数系统中一个重要的数，小于一切自然数，是介于正数和负数之间唯一的数，记作０”。有时用来表示某种量的基准，如摄氏温度计上的冰点，记作０℃”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-零"},{"id":"glyph-seal-96f7","script":"seal","character":"雷","reading":"léi","description":"léi：(1)由于下雨时带异性电的两块云相接，空中闪电发出的强大的声音～电。～鸣。～动。～雨。～霆。～厉风行。\n(2)军事用的爆炸武器地～。鱼～。布～。扫～。～管。\n(3)姓。\n〔～池〕古水名，在今中国安徽省望江县。现用于成语不敢越～～一步”，喻不敢越出一定的范围。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雷"},{"id":"glyph-seal-96f9","script":"seal","character":"雹","reading":"báo","description":"báo：空中水蒸气遇冷结成的冰粒或冰块，常在夏季随暴雨下降冰～。～子。～灾。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-雹"},{"id":"glyph-seal-9700","script":"seal","character":"需","reading":"xū","description":"xū：(1)必得用～求。～要。必～。急～。\n(2)必得用的财物军～。民～。\n(3)等待。\n(4)迟疑。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-需"},{"id":"glyph-seal-9701","script":"seal","character":"霁","reading":"jì","description":"雨后或雪后转晴\n怒气消散,脸色转和","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霁"},{"id":"glyph-seal-9704","script":"seal","character":"霄","reading":"xiāo","description":"xiāo：(1)云云～。～汉（ａ．云霄和天河，指天空ｂ．古代喻朝廷）。\n(2)天空九～。重（chóng）～。～壤（天和地，喻相去很远）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霄"},{"id":"glyph-seal-9706","script":"seal","character":"霆","reading":"tíng","description":"tíng：(1)劈雷，霹雳雷～万钧。\n(2)震动天冬雷，地冬～，草木夏落而秋荣”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霆"},{"id":"glyph-seal-9707","script":"seal","character":"震","reading":"zhèn","description":"zhèn：(1)疾雷（霹雳）使物体振动～夷伯之庙”。～霆。\n(2)雷烨烨～电。”\n(3)巨大的力等使物体剧烈颤动～撼。～荡。～颤。～响。～动。声～遐迩。\n(4)迅速或剧烈地颤动地～。身子不由得一～。\n(5)特指地震”～灾。～源。～中。～级。～情。防～。抗～。余～。\n(6)惊恐或情绪过分激动～惊。～怒。～骇。～慑。\n〔～旦〕佛教经籍中的译名，指中国。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-震"},{"id":"glyph-seal-9709","script":"seal","character":"霉","reading":"méi","description":"méi：(1)低等植物，真菌的一类，常寄生在食物和衣服的表面，呈细丝状，有分枝，没有叶绿素～菌。白～。青～。\n(2)食品、衣物等受了潮热长霉菌发～。～烂。～变。～气。～豆腐。\n〔倒（dǎo）～〕遇事不利，遭遇不好。亦作倒楣”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霉"},{"id":"glyph-seal-970d","script":"seal","character":"霍","reading":"huò","description":"huò：(1)快，迅速～闪（闪电）。～地。～然。\n(2)姓。\n〔～～〕ａ．形容摩擦声、鸟翅振动声、笑声等；ｂ．形容快速闪动。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霍"},{"id":"glyph-seal-970e","script":"seal","character":"霎","reading":"shà","description":"shà：(1)小雨～～（形容雨声）。\n(2)极短的时间～时。～那。一～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霎"},{"id":"glyph-seal-970f","script":"seal","character":"霏","reading":"fēi","description":"fēi：(1)飘扬烟～云敛。\n(2)云气云霞收夕～”。～～（雨、雪、烟、云很盛的样子）。～微（雾气、细雨弥漫的样子）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霏"},{"id":"glyph-seal-9713","script":"seal","character":"霓","reading":"ní","description":"ní：虹的一种，亦称副虹”。形成的原因和虹相同，只是光线在水珠中的反射多了一次，红色在内，紫色在外。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霓"},{"id":"glyph-seal-9716","script":"seal","character":"霖","reading":"lín","description":"lín：久下不停的雨～雨。～沥。～～。甘～（ａ．对农作物有利的雨；ｂ．喻恩泽）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霖"},{"id":"glyph-seal-971c","script":"seal","character":"霜","reading":"shuāng","description":"shuāng：(1)附着在地面或植物上面的微细冰粒，是接近地面的水蒸气冷至摄氏零度以下凝结而成的～降。～冻。～序（指深秋季节）。～秋。～期。～天。\n(2)像霜一样的东西柿～。西瓜～。\n(3)形容白色～鬓。～刃。～锋。\n(4)喻高洁～操（高洁的节操）。～骨。～情。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-霜"}];
